(async () => {
  const { existsSync } = await import('node:fs');
  const inputPath = process.env.INPUT_PATH;
  const outputPath = process.env.OUTPUT_PATH;
  if (!inputPath) throw new Error('Missing INPUT_PATH env var');
  if (!outputPath) throw new Error('Missing OUTPUT_PATH env var');
  if (!existsSync(inputPath)) throw new Error(`Input file not found: ${inputPath}`);
  globalThis.inputPath = inputPath;
  globalThis.outputPath = outputPath;
})();

(async () => {
  const { readFileSync } = await import('node:fs');
  const { parse } = await import('csv-parse');
  const data = readFileSync(globalThis.inputPath, 'utf8');
  const records = await new Promise((resolve, reject) => {
    parse(data, { delimiter: '\t', columns: true }, (err, output) => {
      if (err) return reject(err);
      resolve(output);
    });
  });
  const jsonString = JSON.stringify(records, null, 2);
  globalThis.jsonString = jsonString;
})();

(async () => {
  const { writeFileSync } = await import('node:fs');
  writeFileSync(globalThis.outputPath, globalThis.jsonString, 'utf8');
  console.log(JSON.stringify({ output_path: globalThis.outputPath }));
})();
